  let top = at(c, x0, y0) * (1.0 - fx) + at(c, x0 + 1, y0) * fx;
  let low = at(c, x0, y0 + 1) * (1.0 - fx) + at(c, x0 + 1, y0 + 1) * fx;
  dst[(c * d.oh + id.y) * d.ow + id.x] = top * (1.0 - fy) + low * fy;
